import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/var/app/uploads'
REPORT_DIR = '/var/app/reports'

# Configuration loaded at startup
with open('/etc/app/config.yaml', 'r') as f:
    config = yaml.safe_load(f)

ALLOWED_FORMATS = config.get('allowed_formats', ['pdf', 'docx', 'xlsx'])
MAX_FILE_SIZE = config.get('max_file_size', 10 * 1024 * 1024)

def sanitize_filename(name):
    """Remove directory traversal but preserve extension"""
    name = secure_filename(name)
    if not name:
        return None
    return name

def get_file_metadata(filepath):
    """Extract metadata using exiftool for audit logging"""
    try:
        result = subprocess.run(
            ['exiftool', '-json', filepath],
            capture_output=True, text=True, timeout=10
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return '{}'

def convert_document(input_path, output_format):
    """Convert document to requested format using LibreOffice"""
    output_dir = tempfile.mkdtemp(dir=REPORT_DIR)
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}'
    proc = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = proc.communicate(timeout=30)
    if proc.returncode != 0:
        raise RuntimeError(f'Conversion failed: {stderr.decode()}')
    # Find the output file
    for f in os.listdir(output_dir):
        if f.endswith(f'.{output_format}'):
            return os.path.join(output_dir, f)
    raise RuntimeError('Output file not found')

@app.route('/api/v1/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    filename = sanitize_filename(file.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    if ext not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format not allowed. Allowed: {ALLOWED_FORMATS}'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    file.save(filepath)

    # Size check after save (to handle streaming)
    if os.path.getsize(filepath) > MAX_FILE_SIZE:
        os.unlink(filepath)
        return jsonify({'error': 'File too large'}), 413

    metadata = get_file_metadata(filepath)
    return jsonify({'status': 'uploaded', 'filename': filename, 'metadata': metadata}), 201

@app.route('/api/v1/convert', methods=['POST'])
def convert_file():
    data = request.get_json()
    if not data or 'filename' not in data or 'format' not in data:
        return jsonify({'error': 'Missing filename or format'}), 400

    filename = sanitize_filename(data['filename'])
    output_format = data['format'].strip().lower()

    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    # Validate output format
    if output_format not in ['pdf', 'docx', 'xlsx', 'csv', 'html']:
        return jsonify({'error': 'Unsupported output format'}), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(input_path):
        return jsonify({'error': 'File not found'}), 404

    try:
        output_path = convert_document(input_path, output_format)
        return send_file(output_path, as_attachment=True)
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/preview', methods=['GET'])
def preview_file():
    filename = request.args.get('file', '')
    page = request.args.get('page', '1')

    safe_name = sanitize_filename(filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    # Generate PNG preview of specific page
    output = tempfile.NamedTemporaryFile(suffix='.png', delete=False, dir=REPORT_DIR)
    cmd = f'convert {filepath}[{page}] -resize 800x600 {output.name}'
    subprocess.run(cmd, shell=True, timeout=15)
    return send_file(output.name, mimetype='image/png')

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(REPORT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
